/**
 * @summary Get employees ranked by revenue with progress bar data
 */
export const getGetEmployeeRankingUrl = (params?: GetEmployeeRankingParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/dashboard/employee-ranking?${stringifiedParams}`
    : `/api/dashboard/employee-ranking`;
};

